      class ProtoWriter {
        constructor() {
          this.chunks = [];
          this.scratch = [];
          this.length = 0;
        }

        flush() {
          if (this.scratch.length === 0) return;
          const chunk = Uint8Array.from(this.scratch);
          this.chunks.push(chunk);
          this.scratch = [];
        }

        byte(value) {
          this.scratch.push(value & 255);
          this.length += 1;
        }

        bytes(value) {
          this.flush();
          this.chunks.push(value);
          this.length += value.length;
        }

        varint(value) {
          let next = Number(value) >>> 0;
          while (next > 127) {
            this.byte((next & 127) | 128);
            next >>>= 7;
          }
          this.byte(next);
        }

        tag(field, wireType) {
          this.varint((field << 3) | wireType);
        }

        uint32(field, value) {
          this.tag(field, 0);
          this.varint(value);
        }

        float32(field, value) {
          const buffer = new ArrayBuffer(4);
          new DataView(buffer).setFloat32(0, Number(value) || 0, true);
          this.tag(field, 5);
          this.bytes(new Uint8Array(buffer));
        }

        string(field, value) {
          const encoded = new TextEncoder().encode(String(value || ""));
          this.tag(field, 2);
          this.varint(encoded.length);
          this.bytes(encoded);
        }

        rawBytes(field, value) {
          this.tag(field, 2);
          this.varint(value.length);
          this.bytes(value);
        }

        message(field, callback) {
          const nested = new ProtoWriter();
          callback(nested);
          const encoded = nested.finish();
          this.tag(field, 2);
          this.varint(encoded.length);
          this.bytes(encoded);
        }

        finish() {
          this.flush();
          const output = new Uint8Array(this.length);
          let offset = 0;
          for (const chunk of this.chunks) {
            output.set(chunk, offset);
            offset += chunk.length;
          }
          return output;
        }
      }

