      const particleDefaultSizeForSystemType = (systemType) =>
        normalizeParticleSystemType(systemType) === "sparkle"
          ? PARTICLE_SPARKLE_DEFAULT_SIZE
          : PARTICLE_DEFAULT_SIZE;

      const normalizeParticleShape = (shape, systemType = "falling") => {
        const normalizedSystemType = normalizeParticleSystemType(systemType);
        const candidate = String(shape || "");
        if (normalizedSystemType === "sparkle") {
          return ["polygon", "star", "flash", "circle"].includes(candidate)
            ? candidate
            : "polygon";
        }
        return ["snow", "star", "flash", "circle"].includes(candidate)
          ? candidate
          : "snow";
      };

      const normalizeParticlePolygonSides = (value) => {
        const numericValue = Number(value);
        const resolvedValue = Number.isFinite(numericValue)
          ? numericValue
          : PARTICLE_POLYGON_DEFAULT_SIDES;
        return Math.max(
          PARTICLE_POLYGON_MIN_SIDES,
          Math.min(
            PARTICLE_POLYGON_MAX_SIDES,
            Math.round(resolvedValue),
          ),
        );
      };

      const particleGlowSizeValue = (effect) => {
        const numericValue = Number(
          effect?.particleGlowSize ?? PARTICLE_GLOW_DEFAULT_SIZE,
        );
        return clamp(
          Number.isFinite(numericValue)
            ? numericValue
            : PARTICLE_GLOW_DEFAULT_SIZE,
          0,
          PARTICLE_GLOW_MAX_SIZE,
        );
      };

      const particleGlowStrengthValue = (effect) => {
        const numericValue = Number(
          effect?.particleGlowStrength ??
            effect?.sparkleIntensity ??
            PARTICLE_GLOW_DEFAULT_STRENGTH,
        );
        return clamp(
          Number.isFinite(numericValue)
            ? numericValue
            : PARTICLE_GLOW_DEFAULT_STRENGTH,
          0,
          1,
        );
      };

      const particleGlowLayerStrength = (effect) => {
        const strength = particleGlowStrengthValue(effect);
        if (strength <= 0) return 0;
        const boostProgress = clamp((strength - 0.6) / 0.4, 0, 1);
        const easedBoost =
          boostProgress * boostProgress * (3 - 2 * boostProgress);
        return strength + easedBoost * 0.55;
      };

      const particleDisplaySizeMultiplier = (effect) =>
        normalizeParticleSystemType(effect?.particleSystemType) === "sparkle"
          ? PARTICLE_SPARKLE_SIZE_MULTIPLIER
          : 1;

