          x: index % 10 / 10, y: Math.floor(index / 10) / 10,
          dx: (rng() - 0.5) * 0.9, dy: (rng() - 0.5) * 0.9,
          stagger: rng() * 0.25, turn: (rng() - 0.5) * Math.PI * 2,
