        const x = Math.round(tile.x * width), y = Math.round(tile.y * height);
        const right = Math.round((tile.x + 0.1) * width), bottom = Math.round((tile.y + 0.1) * height);
        const alpha = (1 - fadeSmooth((amount - 0.55) / 0.45)) * (1 - opacityVariation * amount * 0.75);
