        const particleSize = clamp(Number(effect.fadeParticleSize ?? 1), 0.2, 2.5);
        const opacityVariation = clamp(Number(effect.fadeParticleOpacity ?? 1), 0, 1);
        const time = (Number(frameIndex) || 0) / Math.max(1, Number(fps) || 1);
