      $("exportOtherMenu").addEventListener("keydown", (event) => {
        if (event.key === "Escape") {
          event.preventDefault();
          event.stopPropagation();
          setExportOtherMenuOpen(false, { restoreFocus: true });
          return;
        }
        if (event.key === "Tab") {
          setExportOtherMenuOpen(false);
          return;
        }
        const items = exportOtherMenuItems();
        if (!items.length) return;
        const currentIndex = Math.max(0, items.indexOf(document.activeElement));
        let nextIndex = currentIndex;
        if (event.key === "ArrowDown") nextIndex = positiveModulo(currentIndex + 1, items.length);
        else if (event.key === "ArrowUp") nextIndex = positiveModulo(currentIndex - 1, items.length);
        else if (event.key === "Home") nextIndex = 0;
        else if (event.key === "End") nextIndex = items.length - 1;
        else {
          return;
        }
        event.preventDefault();
        items[nextIndex]?.focus();
      });

      $("exportOtherMenu").addEventListener("click", (event) => {
        const settingsButton = event.target.closest("[data-export-settings]");
        if (settingsButton) {
          event.preventDefault();
          event.stopPropagation();
          if (!settingsButton.disabled) {
            openExportFormatSettings(settingsButton.dataset.exportSettings || "", settingsButton);
          }
          return;
        }
        const exportButton = event.target.closest("[data-export-format]");
        if (!exportButton || exportButton.disabled) return;
        event.preventDefault();
        event.stopPropagation();
        const format = exportButton.dataset.exportFormat || "";
        setExportOtherMenuOpen(false);
        void (async () => {
          try {
            setBusy(true);
            const result = await runOtherExport(format);
            const size = Number(result?.bytes || 0);
            const sizeText = size > 0 ? ` (${Math.round(size / 1024)} KB)` : "";
            log(`已导出 ${result?.filename || EXPORT_FORMAT_LABELS[format] || format}${sizeText}。`);
            postPlugin("analytics-track", { event: `${format}_export` });
          } catch (error) {
            log(`${EXPORT_FORMAT_LABELS[format] || format} 导出失败: ${error.message}`);
          } finally {
            setExportModal(false);
            setBusy(false);
          }
        })();
      });

